def parse_duration(s):
    if not s:
        return None

    s = s.replace('h', ' 3600 ').replace('m', ' 60 ').replace('s', ' ')
    s = s.strip()

    if not s:
        return None

    try:
        return int(sum(int(x) for x in s.split()))
    except ValueError:
        return None
